import json, sys

def brief(s, n=300):
    s = str(s)
    return s[:n] + ('...[%d more chars]' % (len(s)-n) if len(s) > n else '')

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(f'[{i}] PARSE ERROR {e}')
            continue
        ts = d.get('timestamp', '')
        typ = d.get('type', d.get('attachment', {}).get('type', '?'))
        msg = d.get('message')
        if msg:
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                print(f'[{i}] {ts} {role} TEXT: {brief(content)}')
            elif isinstance(content, list):
                for c in content:
                    ctype = c.get('type')
                    if ctype == 'text':
                        print(f'[{i}] {ts} {role} TEXT: {brief(c.get("text",""))}')
                    elif ctype == 'tool_use':
                        print(f'[{i}] {ts} {role} TOOL_USE {c.get("name")}: {brief(c.get("input"))}')
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        print(f'[{i}] {ts} {role} TOOL_RESULT: {brief(cont)}')
                    else:
                        print(f'[{i}] {ts} {role} {ctype}: {brief(c)}')
        else:
            att = d.get('attachment')
            if att:
                print(f'[{i}] {ts} ATTACH {att.get("type")}/{att.get("hookName","")}: {brief(att.get("content",""), 150)}')
            else:
                print(f'[{i}] {ts} OTHER type={typ}: {brief(d, 150)}')

